import React, { useState } from 'react';

function AuthScreen({ onBack }) {
  const [isLogin, setIsLogin] = useState(true);

  return (
    <div>
      <button className="btn mb-4 fw-bold text-white border-0" style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)' }} onClick={onBack}>⬅ Quay lại trang chủ</button>
      <div className="card p-4 shadow border-0 mx-auto bg-white" style={{ maxWidth: '400px', borderRadius: '20px', backgroundColor: '#faf5ff' }}>
        <h3 className="text-center fw-bold mb-4" style={{ color: '#7c3aed' }}>{isLogin ? 'ĐĂNG NHẬP TÀI KHOẢN' : 'ĐĂNG KÝ THÀNH VIÊN'}</h3>
        
        <form onSubmit={(e) => { e.preventDefault(); alert(isLogin ? "Đăng nhập thành công!" : "Đăng ký thành công!"); onBack(); }}>
          <div className="mb-3">
            <label className="form-label fw-bold small" style={{ color: '#6b7280' }}>Địa chỉ Email</label>
            <input type="email" className="form-control py-2" style={{ borderRadius: '12px', border: '1px solid #e5e7eb' }} placeholder="name@example.com" required />
          </div>
          <div className="mb-3">
            <label className="form-label fw-bold small" style={{ color: '#6b7280' }}>Mật khẩu</label>
            <input type="password" className="form-control py-2" style={{ borderRadius: '12px', border: '1px solid #e5e7eb' }} placeholder="••••••••" required />
          </div>
          {!isLogin && (
            <div className="mb-3">
              <label className="form-label fw-bold small text-secondary">Nhập lại mật khẩu</label>
              <input type="password" className="form-control py-2" placeholder="••••••••" required />
            </div>
          )}
          <button type="submit" className="btn w-100 fw-bold mt-3 py-2 text-white border-0" style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)' }}>{isLogin ? 'Đăng Nhập' : 'Đăng Ký'}</button>
        </form>
        
        <p className="text-center mt-4 mb-0 small fw-bold" style={{ color: '#7c3aed', cursor: 'pointer', textDecoration: 'underline' }} onClick={() => setIsLogin(!isLogin)}>
          {isLogin ? 'Chưa có tài khoản? Đăng ký ngay' : 'Đã có tài khoản thành viên? Đăng nhập'}
        </p>
      </div>
    </div>
  );
}

export default AuthScreen;
